#include <vector>

class Solution {
public:
    int minReorder(int n, std::vector<std::vector<int>>& connections) {
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (const auto& c : connections) {
            adj[c[0]].push_back({c[1], 1});
            adj[c[1]].push_back({c[0], 0});
        }
        std::vector<bool> visited(n, false);
        visited[0] = true;
        int reorders = 0;
        std::vector<int> stack = {0};
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            for (const auto& [v, cost] : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    reorders += cost;
                    stack.push_back(v);
                }
            }
        }
        return reorders;
    }
};

import java.util.*;

class Solution {
    public int minReorder(int n, int[][] connections) {
        List<List<int[]>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] c : connections) {
            adj.get(c[0]).add(new int[]{c[1], 1});
            adj.get(c[1]).add(new int[]{c[0], 0});
        }
        boolean[] visited = new boolean[n];
        visited[0] = true;
        int reorders = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int[] edge : adj.get(u)) {
                int v = edge[0], cost = edge[1];
                if (!visited[v]) {
                    visited[v] = true;
                    reorders += cost;
                    stack.push(v);
                }
            }
        }
        return reorders;
    }
}

var minReorder = function(n, connections) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of connections) {
        adj[u].push([v, 1]);
        adj[v].push([u, 0]);
    }
    const visited = new Array(n).fill(false);
    visited[0] = true;
    let reorders = 0;
    const stack = [0];
    while (stack.length > 0) {
        const u = stack.pop();
        for (const [v, cost] of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                reorders += cost;
                stack.push(v);
            }
        }
    }
    return reorders;
};
